// memory: 256 cells; registers R0, R1
const mem = new Array(256).fill(0);
mem[100] = 7;            // a value already sitting in memory
const R = { R0: 0, R1: 5 };

// the program: a list of instructions, run one at a time
R.R0 = mem[100];         // LOAD  R0, 100   (read cell 100 into R0)
R.R0 = R.R0 + R.R1;      // ADD   R0, R1    (R0 = R0 + R1)
mem[200] = R.R0;         // STORE 200, R0   (write R0 to cell 200)
